1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .p-I { background: #00c8e0 !important; }
27	  .p-O { background: #f0d000 !important; }
28	  .p-T { background: #a040f0 !important; }
29	  .p-S { background: #30c050 !important; }
30	  .p-Z { background: #e03030 !important; }
31	  .p-J { background: #3060f0 !important; }
32	  .p-L { background: #f08c20 !important; }
33	</style>
34	</head>
35	<body>
36	<div class="game">
37	  <div class="board" data-testid="board" id="board"></div>
38	  <div class="side">
39	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
40	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
41	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
42	    <div class="stat"><div class="label">Next</div><div id="next"></div></div>
43	    <div class="help">← → move<br>↓ soft drop<br>Space hard drop</div>
44	  </div>
45	</div>
46	<script>
47	(function () {
48	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
49	
50	  // [REQ-001] spawn shapes as [row, col] on the board
51	  var SHAPES = {
52	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
53	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
54	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
55	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
56	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
57	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
58	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
59	  };
60	
61	  var state = {
62	    board: [],      // board[row][col] = letter or null
63	    current: null,  // { type, cells: [[r,c],...] }
64	    upcoming: [],
65	    score: 0, level: 1, lines: 0,
66	    status: "running"
67	  };
68	  var timer = null;
69	
70	  var boardEl = document.getElementById("board");
71	  var cellEls = [];
72	  for (var r = 0; r < ROWS; r++) {
73	    cellEls.push([]);
74	    for (var c = 0; c < COLS; c++) {
75	      var el = document.createElement("div");
76	      el.className = "cell";
77	      el.setAttribute("data-testid", "cell");
78	      el.setAttribute("data-row", r);
79	      el.setAttribute("data-col", c);
80	      boardEl.appendChild(el);
81	      cellEls[r].push(el);
82	    }
83	  }
84	
85	  function emptyBoard() {
86	    var b = [];
87	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
88	    return b;
89	  }
90	
91	  function randomLetter() {
92	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
93	  }
94	
95	  function validLetters(queue) {
96	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
97	  }
98	
99	  // [REQ-001] take the next piece from the queue, falling back to random
100	  function takeNext() {
101	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
102	    if (!state.upcoming.length) state.upcoming.push(randomLetter());
103	    return letter;
104	  }
105	
106	  function spawn() {
107	    var type = takeNext();
108	    state.current = { type: type, cells: SHAPES[type].map(function (p) { return [p[0], p[1]]; }) };
109	  }
110	
111	  function fits(cells) {
112	    return cells.every(function (p) {
113	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
114	    });
115	  }
116	
117	  function tryMove(dr, dc) {
118	    if (!state.current) return false;
119	    var moved = state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
120	    if (!fits(moved)) return false;
121	    state.current.cells = moved;
122	    return true;
123	  }
124	
125	  // [REQ-001] lock the falling piece and spawn the next one
126	  function lock() {
127	    var cur = state.current;
128	    cur.cells.forEach(function (p) {
129	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
130	    });
131	    spawn();
132	  }
133	
134	  // [REQ-001] one gravity step: used by the real timer and by tick()
135	  function gravityStep() {
136	    if (state.status !== "running") return;
137	    if (!state.current) spawn();
138	    else if (!tryMove(1, 0)) lock();
139	    render();
140	  }
141	
142	  // [REQ-001] player actions
143	  function input(action) {
144	    if (state.status !== "running" || !state.current) return;
145	    if (action === "left") tryMove(0, -1);
146	    else if (action === "right") tryMove(0, 1);
147	    else if (action === "softDrop") tryMove(1, 0);
148	    else if (action === "hardDrop") { while (tryMove(1, 0)) {} lock(); }
149	    render();
150	  }
151	
152	  // [REQ-001] synchronous render from the real game state
153	  function render() {
154	    var drawn = state.board.map(function (row) { return row.slice(); });
155	    if (state.current) {
156	      state.current.cells.forEach(function (p) {
157	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
158	      });
159	    }
160	    for (var r = 0; r < ROWS; r++) {
161	      for (var c = 0; c < COLS; c++) {
162	        var el = cellEls[r][c], letter = drawn[r][c];
163	        el.className = letter ? "cell p-" + letter : "cell";
164	        el.setAttribute("data-filled", letter ? "true" : "false");
165	        el.setAttribute("data-piece", letter || "");
166	      }
167	    }
168	    document.getElementById("score").textContent = String(state.score);
169	    document.getElementById("level").textContent = String(state.level);
170	    document.getElementById("lines").textContent = String(state.lines);
171	    renderNext();
172	  }
173	
174	  function renderNext() {
175	    var box = document.getElementById("next");
176	    box.innerHTML = "";
177	    state.upcoming.slice(0, 3).forEach(function (type) {
178	      var grid = document.createElement("div");
179	      grid.className = "preview";
180	      var filled = {};
181	      SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
182	      for (var r = 0; r < 2; r++) {
183	        for (var c = 0; c < 4; c++) {
184	          var m = document.createElement("div");
185	          m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
186	          grid.appendChild(m);
187	        }
188	      }
189	      box.appendChild(grid);
190	    });
191	  }
192	
193	  function startTimer() {
194	    if (timer) clearInterval(timer);
195	    timer = setInterval(gravityStep, 1000);
196	  }
197	
198	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
199	  function newGame(queue) {
200	    state.board = emptyBoard();
201	    state.score = 0; state.level = 1; state.lines = 0;
202	    state.status = "running";
203	    state.upcoming = validLetters(queue);
204	    state.current = null;
205	    spawn();
206	    startTimer();
207	    render();
208	  }
209	
210	  // [REQ-001] test control surface
211	  window.__tetris = {
212	    newGame: newGame,
213	    setQueue: function (queue) {
214	      state.upcoming = validLetters(queue);
215	      render();
216	    },
217	    setBoard: function (rows) {
218	      var b = emptyBoard();
219	      for (var r = 0; r < ROWS; r++) {
220	        var line = (rows && rows[r]) || "";
221	        for (var c = 0; c < COLS; c++) {
222	          var ch = line.charAt(c);
223	          b[r][c] = SHAPES[ch] ? ch : null;
224	        }
225	      }
226	      state.board = b;
227	      render();
228	    },
229	    tick: function (n) {
230	      if (n === undefined) n = 1;
231	      for (var i = 0; i < n; i++) gravityStep();
232	    },
233	    input: input,
234	    getBoard: function () {
235	      return state.board.map(function (row) {
236	        return row.map(function (v) { return v || "."; }).join("");
237	      });
238	    },
239	    getState: function () {
240	      return {
241	        current: state.current
242	          ? { type: state.current.type, cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }) }
243	          : null,
244	        next: state.upcoming.slice(),
245	        score: state.score, level: state.level, lines: state.lines,
246	        status: state.status
247	      };
248	    }
249	  };
250	
251	  document.addEventListener("keydown", function (e) {
252	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", " ": "hardDrop", Spacebar: "hardDrop" };
253	    var action = map[e.key];
254	    if (!action) return;
255	    e.preventDefault();
256	    input(action);
257	  });
258	
259	  newGame();
260	})();
261	</script>
262	</body>
263	</html>
