p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
  };
''','''    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
  };

  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
  var BOX = {
    I: { size: 4, origin: [-1, 3] },
    O: { size: 2, origin: [0, 4] },
    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
  };
  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
''')
rep('''    current: null,  // { type, cells: [[r,c],...] }''','''    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }''')
rep('''    state.current = { type: type, cells: SHAPES[type].map(function (p) { return [p[0], p[1]]; }) };''',
'''    state.current = {
      type: type,
      cells: SHAPES[type].map(function (p) { return [p[0], p[1]]; }),
      origin: BOX[type].origin.slice(),
      lockTicks: 0, lockResets: 0
    };''')
rep('''  function tryMove(dr, dc) {
    if (!state.current) return false;
    var moved = state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
    if (!fits(moved)) return false;
    state.current.cells = moved;
    return true;
  }
''','''  function canMove(dr, dc) {
    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
  }

  function tryMove(dr, dc) {
    if (!state.current || !canMove(dr, dc)) return false;
    var cur = state.current;
    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
    if (dr > 0) cur.lockTicks = 0;
    return true;
  }

  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
  function tryRotateCW() {
    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
    var turned = cur.cells.map(function (p) {
      var lr = p[0] - o[0], lc = p[1] - o[1];
      return [o[0] + lc, o[1] + n - 1 - lr];
    });
    // a rotation near the top edge is pushed down just enough to stay on the board
    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
    for (var i = 0; i < KICKS.length; i++) {
      var dc = KICKS[i];
      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
      if (fits(cand)) {
        cur.cells = cand;
        cur.origin = [o[0] + dr, o[1] + dc];
        return true;
      }
    }
    return false;
  }

  // [REQ-002] sideways move; while resting it restarts the lock delay, at most MAX_LOCK_RESETS times
  function shift(dc) {
    var resting = !canMove(1, 0);
    if (!tryMove(0, dc) || !resting) return;
    var cur = state.current;
    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
  }
''')
rep('''  // [REQ-001] one gravity step: used by the real timer and by tick()
  function gravityStep() {
    if (state.status !== "running") return;
    if (!state.current) spawn();
    else if (!tryMove(1, 0)) lock();
    render();
  }''','''  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
  function gravityStep() {
    if (state.status !== "running") return;
    if (!state.current) spawn();
    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
    render();
  }''')
rep('''  // [REQ-001] player actions
  function input(action) {
    if (state.status !== "running" || !state.current) return;
    if (action === "left") tryMove(0, -1);
    else if (action === "right") tryMove(0, 1);''','''  // [REQ-001] [REQ-002] player actions; hard drop locks at once, with no delay
  function input(action) {
    if (state.status !== "running" || !state.current) return;
    if (action === "left") shift(-1);
    else if (action === "right") shift(1);
    else if (action === "rotateCW") tryRotateCW();''')
rep('''          ? { type: state.current.type, cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }) }''',
'''          ? {
              type: state.current.type,
              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
              lockTicks: state.current.lockTicks,
              lockResets: state.current.lockResets
            }''')
rep('''ArrowDown: "softDrop", " ": "hardDrop"''','''ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop"''')
rep('''← → move<br>↓ soft drop''','''← → move<br>↑ or X rotate<br>↓ soft drop''')
open(p,'w').write(s)
EOF
